  "examples/advanced.cc": "#include <filesystem>\n#include <iostream>\n\n#include \"cli/argument.hh\"\n#include \"cli/parser.hh\"\n\nnamespace fs = std::filesystem;\n\nstruct Args {\n  cli::Description description{\n      \"Action-pipeline example using Arg, filesystem conversion, and\"\n      \" collection-valued options.\"};\n\n  cli::Arg<\"help\", 'h', cli::action::print_help | cli::action::exit_success,\n           cli::nargs::none>\n      help{{.help = \"Show help and exit\"}};\n\n  cli::Arg<\"config\", 'c',\n           cli::conversion::path | cli::validation::exists |\n               cli::validation::is_regular_file | cli::pack::set_once>\n      config{{.help = \"Configuration file\", .presence = cli::required}};\n\n  cli::Arg<\"jobs\", 'j',\n           cli::conversion::integer<int> | cli::validation::range<1, 64> |\n               cli::pack::set_once>\n      jobs{{.help = \"Parallel job count (1-64)\"}};\n\n  cli::Arg<\"include\", 'I',\n           cli::conversion::path | cli::validation::parent_exists |\n               cli::pack::push,\n           cli::nargs::one_or_more>\n      includes{{.help = \"Include directories to add\"}};\n\n  cli::Arg<\"define\", 'D',\n           cli::conversion::string | cli::validation::not_blank |\n               cli::pack::push_unique,\n           cli::nargs::one_or_more>\n      defines{{.help = \"Unique preprocessor definitions\"}};\n};\n\nauto main(int argc, char* argv[]) -> int {\n  const auto args = cli::parse_or_exit<Args>(argc, argv);\n\n  std::cout << \"config: \" << args.config.value()->string() << '\\n';\n  if (args.jobs.value()) {\n    std::cout << \"jobs: \" << *args.jobs.value() << '\\n';\n  }\n  for (const fs::path& include_dir : args.includes.value()) {\n    std::cout << \"include: \" << include_dir.string() << '\\n';\n  }\n  for (const std::string& define : args.defines.value()) {\n    std::cout << \"define: \" << define << '\\n';\n  }\n  return 0;\n}\n",
  "examples/bind.cc": "// bind.cc — demonstrates BoundOption writing directly into application state.\n\n#include <iostream>\n\n#include \"cli/argument.hh\"\n#include \"cli/parser.hh\"\n\nstruct Args {\n  cli::Description description{\n      \"Bind parsed values into pre-existing variables instead of reading them\"\n      \" back from Args.\"};\n  cli::Help<> help;\n  cli::BoundIntOption<\"port\", 'p'> port;\n  cli::BoundStringOption<\"output\", 'o'> output;\n  cli::BoundDoubleOption<\"ratio\"> ratio;\n};\n\nauto main(int argc, char* argv[]) -> int {\n  int port = 8080;\n  std::string output = \"out.bin\";\n  double ratio = 1.0;\n\n  Args args;\n  args.port.bind(port);\n  args.output.bind(output);\n  args.ratio = &ratio;\n\n  const auto result = cli::Parser<Args>{}.parse(std::move(args), argc, argv);\n  if (!result) {\n    std::cerr << result.error.message() << '\\n';\n    return result.error.exit_code();\n  }\n\n  std::cout << \"port: \" << port << '\\n';\n  std::cout << \"output: \" << output << '\\n';\n  std::cout << \"ratio: \" << ratio << '\\n';\n  return 0;\n}\n",
  "examples/callback_entry_point.cc": "// callback_entry_point.cc — demonstrates using on_parse callbacks to populate\n// an application state object before handing off to the real entry point.\n\n#include <iostream>\n\n#include \"cli/argument.hh\"\n#include \"cli/parser.hh\"\n\nstruct AppState {\n  bool verbose = false;\n  int jobs = 1;\n  std::vector<std::string> includes;\n  std::vector<std::string> inputs;\n};\n\nstruct Args {\n  cli::Description description{\n      \"Populate application state via callbacks, then call the real entry \"\n      \"point.\"};\n  cli::Help<> help;\n  cli::Flag<\"verbose\", 'v'> verbose;\n  cli::IntOption<\"jobs\", 'j'> jobs;\n  cli::ListOption<std::string, \"include\", 'I', cli::nargs::exactly<1>> includes;\n  cli::Positional<std::string, cli::nargs::one_or_more> inputs;\n};\n\nauto run(const AppState& state) -> int {\n  std::cout << \"verbose: \" << std::boolalpha << state.verbose << '\\n';\n  std::cout << \"jobs: \" << state.jobs << '\\n';\n  for (const auto& include_dir : state.includes) {\n    std::cout << \"include: \" << include_dir << '\\n';\n  }\n  for (const auto& input : state.inputs) {\n    std::cout << \"input: \" << input << '\\n';\n  }\n  return 0;\n}\n\nauto main(int argc, char* argv[]) -> int {\n  AppState state;\n  Args args;\n\n  args.verbose = cli::Flag<\"verbose\", 'v'>{{\n      .on_parse = [&state](const bool& value) { state.verbose = value; },\n  }};\n  args.jobs = cli::IntOption<\"jobs\", 'j'>{{\n      .on_parse =\n          [&state](const std::optional<int>& value) {\n            if (value) {\n              state.jobs = *value;\n            }\n          },\n  }};\n  args.includes =\n      cli::ListOption<std::string, \"include\", 'I', cli::nargs::exactly<1>>{{\n          .on_parse =\n              [&state](const std::vector<std::string>& value) {\n                state.includes = value;\n              },\n      }};\n  args.inputs = cli::Positional<std::string, cli::nargs::one_or_more>{{\n      .on_parse =\n          [&state](const std::vector<std::string>& value) {\n            state.inputs = value;\n          },\n  }};\n\n  const auto result = cli::Parser<Args>{}.parse(std::move(args), argc, argv);\n  if (!result) {\n    std::cerr << result.error.message() << '\\n';\n    return result.error.exit_code();\n  }\n\n  return run(state);\n}\n",
